/**
 * Checks whether the specified element occurs within this range.
 *
 * @param element  the element to check for, null returns false.
 * @return true if the specified element occurs within this range.
 */
public boolean contains(final T element) {
    if (element == null) {
        return false;
    }
    return comparator.compare(element, minimum) > -1 && comparator.compare(element, maximum) < 1;
}

/**
 * Checks whether this range contains all the elements of the specified range.
 *
 * <p>This method may fail if the ranges have two different comparators or element types.</p>
 *
 * @param otherRange  the range to check, null returns false.
 * @return true if this range contains the specified range.
 * @throws RuntimeException if ranges cannot be compared.
 */
public boolean containsRange(final Range<T> otherRange) {
    if (otherRange == null) {
        return false;
    }
    return contains(otherRange.minimum) && contains(otherRange.maximum);
}

/**
 * Checks where the specified element occurs relative to this range.
 *
 * <p>The API is reminiscent of the Comparable interface returning {@code -1} if
 * the element is before the range, {@code 0} if contained within the range and
 * {@code 1} if the element is after the range.</p>
 *
 * @param element  the element to check for, not null.
 * @return -1, 0 or +1 depending on the element's location relative to the range.
 * @throws NullPointerException if {@code element} is {@code null}.
 */
public int elementCompareTo(final T element) {
    // Comparable API says throw NPE on null
    Objects.requireNonNull(element, "element");
    if (isAfter(element)) {
        return -1;
    }
    if (isBefore(element)) {
        return 1;
    }
    return 0;
}

/**
 * Compares this range to another object to test if they are equal.
 *
 * <p>To be equal, the minimum and maximum values must be equal, which
 * ignores any differences in the comparator.</p>
 *
 * @param obj the reference object with which to compare.
 * @return true if this object is equal.
 */
@Override
public boolean equals(final Object obj) {
    if (obj == this) {
        return true;
    }
    if (obj == null || obj.getClass() != getClass()) {
        return false;
    }
    // OK because we checked the class above
    @SuppressWarnings("unchecked")
    final Range<T> range = (Range<T>) obj;
    return minimum.equals(range.minimum) && maximum.equals(range.maximum);
}

/**
 * Fits the given element into this range by returning the given element or, if out of bounds, the range minimum if
 * below, or the range maximum if above.
 *
 * <pre>{@code
 * Range<Integer> range = Range.between(16, 64);
 * range.fit(-9) -->  16
 * range.fit(0)  -->  16
 * range.fit(15) -->  16
 * range.fit(16) -->  16
 * range.fit(17) -->  17
 * ...
 * range.fit(63) -->  63
 * range.fit(64) -->  64
 * range.fit(99) -->  64
 * }</pre>
 *
 * @param element the element to check for, not null.
 * @return the minimum, the element, or the maximum depending on the element's location relative to the range.
 * @throws NullPointerException if {@code element} is {@code null}.
 * @since 3.10
 */
public T fit(final T element) {
    // Comparable API says throw NPE on null
    Objects.requireNonNull(element, "element");
    if (isAfter(element)) {
        return minimum;
    }
    if (isBefore(element)) {
        return maximum;
    }
    return element;
}

/**
 * Gets the comparator being used to determine if objects are within the range.
 *
 * <p>Natural ordering uses an internal comparator implementation, thus this
 * method never returns null. See {@link #isNaturalOrdering()}.</p>
 *
 * @return the comparator being used, not null.
 */
public Comparator<T> getComparator() {
    return comparator;
}

/**
 * Gets the maximum value in this range.
 *
 * @return the maximum value in this range, not null.
 */
public T getMaximum() {
    return maximum;
}

/**
 * Gets the minimum value in this range.
 *
 * @return the minimum value in this range, not null.
 */
public T getMinimum() {
    return minimum;
}

/**
 * Gets a suitable hash code for the range.
 *
 * @return a hash code value for this object.
 */
@Override
public int hashCode() {
    return hashCode;
}

/**
 * Calculate the intersection of {@code this} and an overlapping Range.
 *
 * @param other overlapping Range.
 * @return range representing the intersection of {@code this} and {@code other} ({@code this} if equal).
 * @throws IllegalArgumentException if {@code other} does not overlap {@code this}.
 * @since 3.0.1
 */
public Range<T> intersectionWith(final Range<T> other) {
    if (!this.isOverlappedBy(other)) {
        throw new IllegalArgumentException(String.format("Cannot calculate intersection with non-overlapping range %s", other));
    }
    if (this.equals(other)) {
        return this;
    }
    final T min = getComparator().compare(minimum, other.minimum) < 0 ? other.minimum : minimum;
    final T max = getComparator().compare(maximum, other.maximum) < 0 ? maximum : other.maximum;
    return of(min, max, getComparator());
}

/**
 * Checks whether this range is after the specified element.
 *
 * @param element  the element to check for, null returns false.
 * @return true if this range is entirely after the specified element.
 */
public boolean isAfter(final T element) {
    if (element == null) {
        return false;
    }
    return comparator.compare(element, minimum) < 0;
}

/**
 * Checks whether this range is completely after the specified range.
 *
 * <p>This method may fail if the ranges have two different comparators or element types.</p>
 *
 * @param otherRange  the range to check, null returns false.
 * @return true if this range is completely after the specified range.
 * @throws RuntimeException if ranges cannot be compared.
 */
public boolean isAfterRange(final Range<T> otherRange) {
    if (otherRange == null) {
        return false;
    }
    return isAfter(otherRange.maximum);
}

/**
 * Checks whether this range is before the specified element.
 *
 * @param element  the element to check for, null returns false.
 * @return true if this range is entirely before the specified element.
 */
public boolean isBefore(final T element) {
    if (element == null) {
        return false;
    }
    return comparator.compare(element, maximum) > 0;
}

/**
 * Checks whether this range is completely before the specified range.
 *
 * <p>This method may fail if the ranges have two different comparators or element types.</p>
 *
 * @param otherRange  the range to check, null returns false.
 * @return true if this range is completely before the specified range.
 * @throws RuntimeException if ranges cannot be compared.
 */
public boolean isBeforeRange(final Range<T> otherRange) {
    if (otherRange == null) {
        return false;
    }
    return isBefore(otherRange.minimum);
}

/**
 * Checks whether this range ends with the specified element.
 *
 * @param element  the element to check for, null returns false.
 * @return true if the specified element occurs within this range.
 */
public boolean isEndedBy(final T element) {
    if (element == null) {
        return false;
    }
    return comparator.compare(element, maximum) == 0;
}

/**
 * Tests whether or not the Range is using the natural ordering of the elements.
 *
 * <p>Natural ordering uses an internal comparator implementation, thus this
 * method is the only way to check if a null comparator was specified.</p>
 *
 * @return true if using natural ordering.
 */
public boolean isNaturalOrdering() {
    return comparator == ComparableComparator.INSTANCE;
}

/**
 * Tests whether this range is overlapped by the specified range.
 *
 * <p>Two ranges overlap if there is at least one element in common.</p>
 *
 * <p>This method may fail if the ranges have two different comparators or element types.</p>
 *
 * @param otherRange  the range to test, null returns false.
 * @return true if the specified range overlaps with this
 *  range; otherwise, {@code false}.
 * @throws RuntimeException if ranges cannot be compared.
 */
public boolean isOverlappedBy(final Range<T> otherRange) {
    if (otherRange == null) {
        return false;
    }
    return otherRange.contains(minimum) || otherRange.contains(maximum) || contains(otherRange.minimum);
}

/**
 * Tests whether this range starts with the specified element.
 *
 * @param element  the element to check for, null returns false.
 * @return true if the specified element occurs within this range.
 */
public boolean isStartedBy(final T element) {
    if (element == null) {
        return false;
    }
    return comparator.compare(element, minimum) == 0;
}

/**
 * Gets the range as a {@link String}.
 *
 * <p>The format of the String is '[<em>min</em>..<em>max</em>]'.</p>
 *
 * @return the {@link String} representation of this range.
 */
@Override
public String toString() {
    if (toString == null) {
        toString = "[" + minimum + ".." + maximum + "]";
    }
    return toString;
}
